    '''
Un envoltorio alrededor de un flujo de bytes que permite leer un número fijo de bytes de una conexión a un servidor. | @param stream: El flujo del que leer. | Lee un número fijo de bytes del flujo.
        @param num_bytes: El número de bytes a leer.
        @return: Los bytes leídos.
        @raise EOFError: En caso de que queden menos de num_bytes bytes en el flujo de bytes subyacente.
    '''

    def __init__(self, stream):
        '''
        @param stream:  The stream to read from.
        '''
        self._stream = stream

    def read_bytes(self, num_bytes: int) -> bytes:
        '''
        Reads a fixed number of bytes from the stream.
        @param num_bytes:  The number of bytes to read.
        @return:    The read bytes.
        @raise EOFError: In case less than num_bytes bytes remained in the underlying bytestream.
        '''
        result = b''
        while num_bytes > 0:
            chunk = self._stream.read(num_bytes)
            if not chunk:
                raise EOFError('Not enough bytes in the stream')
            result += chunk
            num_bytes -= len(chunk)
        return result
